def wslug(w): m=(w-1)//4+1; return f"m{m}w{(w-1)%4+1}"
def wlink(w): return f"[W{w}](/{wslug(w)}.html)"
def link(n,u): return f"[{n}]({u})"
if sys.argv[1]=='page':
  urls={u for d in D for u in [d[2]] if u.startswith('http')}
  out=["=== resources | 参考资料库 | 参考","# 参考资料库",
  f"> 按方向整理的转型参考资料，共 **{len(urls)}** 个不重复的外部链接（部分资源在多个方向重复出现）。链接均于 2026-10-16 至 2026-10-20 期间用 curl 检查过；标 ⚠️ 的会拦截自动化检查，浏览器可正常打开。每个周页面底部也有对应的“参考资料”块。",
  "","**类型**：书 / 文档 / 仓库 / 博客 / 论文 / 课程。**难度**：入门 → 进阶 → 高级。**对应周**：点击跳到使用它的那一周（W1–W24）。","",
  "> 实验需要什么机器、何时租卡，见 [实验资源与成本](/lab-cost.html)。",""]
  out.append("## 目录\n"+"\n".join(f"- [{t}](#{i})" for i,(k,t) in enumerate(DIRS,1))+"\n")
  for i,(k,t) in enumerate(DIRS,1):
    out.append(f'<h2 id="{i}">{t}</h2>\n')
    out.append("| 资源 | 类型 | 难度 | 对应周 | 为什么读 |\n|---|---|---|---|---|")
    for d in D:
      if d[0]==k: out.append(f"| {link(d[1],d[2])} | {d[3]} | {d[4]} | {' '.join(wlink(w) for w in d[5])} | {d[6]} |")
    out.append("")
  out.append("## 实验环境\n- [kind](https://kind.sigs.k8s.io/) ｜ [OrbStack](https://orbstack.dev/) ｜ [AutoDL](https://www.autodl.com/) ｜ [RunPod](https://www.runpod.io/)（价格以平台页面为准）\n")
  print("\n".join(out))
  print(len(urls),file=sys.stderr)
elif sys.argv[1]=='week':
  w=int(sys.argv[2]);seen=set();rows=[]
  for d in D:
    if w in d[5] and d[2] not in seen and d[0]!='cn': seen.add(d[2]);rows.append(f"- {link(d[1],d[2])}（{d[3]}·{d[4]}）：{d[6]}")
  print("\n".join(rows))
